import Foundation
import UserNotifications

/// Presentation only. Codes are generated by the existing native pairing engine.
enum ZagPairingCodeNotification {
    static func validCode(_ code: String) -> String? {
        guard code.utf8.count == 6, code.utf8.allSatisfy({ (48...57).contains($0) }) else { return nil }
        return code
    }

    static func content(for code: String) -> UNMutableNotificationContent? {
        guard let code = validCode(code) else { return nil }
        let content = UNMutableNotificationContent()
        content.title = "Pairing Code"
        content.body = code
        content.sound = .default
        content.categoryIdentifier = "zag-rppairing-pin-category"
        if #available(iOS 15.0, macOS 12.0, *) {
            content.interruptionLevel = .timeSensitive
        }
        return content
    }
}
